{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect meeting notes or transcript",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Meeting notes", "Meeting transcript (if available)"],
        "outputs": ["Raw meeting content"]
      },
      {
        "id": "A2",
        "name": "Clarify unclear items with decision owners",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Raw meeting content", "List of decision owners"],
        "outputs": ["Clarified decisions and action items"]
      },
      {
        "id": "A3",
        "name": "Extract decisions and action items manually",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Raw meeting content", "Clarified decisions and action items"],
        "outputs": ["Decision list", "Action-item assignments"]
      },
      {
        "id": "A4",
        "name": "Draft summary email",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Decision list", "Action-item assignments"],
        "outputs": ["Draft summary email"]
      },
      {
        "id": "A5",
        "name": "Determine recipient list",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Participant list"],
        "outputs": ["Recipient email list"]
      },
      {
        "id": "A6",
        "name": "Send summary email",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Draft summary email", "Recipient email list"],
        "outputs": ["Sent summary email"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are there unclear decisions or action item owners in the raw meeting content?",
        "branches": [
          "Yes — proceed to clarify with decision owners (A2)",
          "No — proceed directly to extract decisions and action items (A3)"
        ]
      },
      {
        "id": "D2",
        "condition": "Is the recipient list complete and valid?",
        "branches": [
          "Yes — proceed to send summary email (A6)",
          "No — exception: incomplete or invalid recipient list; handling procedure not specified"
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "Missing transcript or meeting notes",
        "trigger": "No usable content available after the meeting",
        "handling": "Not specified"
      },
      {
        "id": "E2",
        "description": "Unclear decision owner",
        "trigger": "Responsibility for a decision or action item cannot be determined from available content",
        "handling": "Minute taker may attempt to clarify; no formal fallback defined"
      },
      {
        "id": "E3",
        "description": "Incomplete recipient list",
        "trigger": "Participant list is missing entries or contains invalid addresses",
        "handling": "Not specified"
      },
      {
        "id": "E4",
        "description": "Confidential content included in summary",
        "trigger": "Summary draft contains information that should not be broadly distributed",
        "handling": "Not specified"
      },
      {
        "id": "E5",
        "description": "Email system unavailable",
        "trigger": "Technical failure prevents sending the summary email",
        "handling": "Not specified"
      }
    ],
    "dependencies": [
      {
        "from": "A1",
        "to": "D1",
        "type": "control_flow"
      },
      {
        "from": "D1",
        "to": "A2",
        "type": "control_flow"
      },
      {
        "from": "D1",
        "to": "A3",
        "type": "control_flow"
      },
      {
        "from": "A2",
        "to": "A3",
        "type": "control_flow"
      },
      {
        "from": "A3",
        "to": "A4",
        "type": "control_flow"
      },
      {
        "from": "A4",
        "to": "A5",
        "type": "control_flow"
      },
      {
        "from": "A5",
        "to": "D2",
        "type": "control_flow"
      },
      {
        "from": "D2",
        "to": "A6",
        "type": "control_flow"
      }
    ]
  },
  "automation_opportunities": [
    {
      "target": "A1 — Collect meeting notes or transcript",
      "rationale": "If a recording or transcription service is used during the meeting, the transcript could be automatically retrieved and made available to the minute taker, reducing manual collection effort.",
      "required_data": ["Meeting recording or transcription service output", "Meeting identifier or calendar reference"],
      "constraints": ["Transcription service must be in use during the meeting", "Privacy and consent rules for recording must be satisfied"],
      "confidence": "medium"
    },
    {
      "target": "A3 — Extract decisions and action items manually",
      "rationale": "AI-based summarization tools could parse the transcript or notes to automatically extract decisions and action-item assignments, reducing manual effort and processing time.",
      "required_data": ["Raw meeting transcript or notes", "Structured output schema for decisions and action items"],
      "constraints": ["AI output accuracy must be validated before use", "Confidential content handling must be addressed", "Current process is fully manual; tooling would need to be introduced"],
      "confidence": "medium"
    },
    {
      "target": "A4 — Draft summary email",
      "rationale": "A template-based system could auto-populate a structured email draft from the extracted decision list and action-item assignments, ensuring consistent formatting and reducing drafting time.",
      "required_data": ["Decision list", "Action-item assignments", "Email template definition"],
      "constraints": ["A formal template must first be defined and agreed upon", "Confidential content detection should be incorporated before auto-drafting"],
      "confidence": "medium"
    },
    {
      "target": "A5 — Determine recipient list",
      "rationale": "The recipient list could be automatically derived from the meeting calendar invite or participant list, eliminating manual selection and reducing the risk of omissions.",
      "required_data": ["Meeting calendar invite", "Participant list with valid email addresses"],
      "constraints": ["Calendar system integration required", "Method for determining recipient list is currently unspecified; assumptions must be validated"],
      "confidence": "low"
    },
    {
      "target": "A6 — Send summary email",
      "rationale": "Once the draft is approved or validated, automated email dispatch could be triggered without manual sending, integrating with the email system directly.",
      "required_data": ["Finalized draft summary email", "Validated recipient email list"],
      "constraints": ["Email system API or integration must be available", "No formal approval step currently exists; automated sending carries risk without a review gate"],
      "confidence": "low"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "The exact method used by the minute taker to determine the recipient list is unspecified — it is unclear whether it is drawn from the meeting invite, a standing distribution list, or selected ad hoc."
    },
    {
      "id": "G2",
      "description": "No formal review or approval step is defined before the summary email is sent; it is unknown whether one is expected or desired by stakeholders."
    },
    {
      "id": "G3",
      "description": "No mandatory email template or named section structure has been formally defined, making consistent formatting dependent on individual practice."
    },
    {
      "id": "G4",
      "description": "Handling procedures for all identified exceptions (missing transcript, unclear decision owner, incomplete recipient list, confidential content, email system unavailability) are not specified."
    },
    {
      "id": "G5",
      "description": "The systems used for note-taking, email drafting, and email sending are unknown, which limits the ability to assess integration feasibility for automation."
    },
    {
      "id": "G6",
      "description": "It is unclear whether the clarification step with decision owners (A2) is always performed or only triggered under specific conditions, and what channel is used for that clarification."
    },
    {
      "id": "G7",
      "description": "No timeout or escalation policy exists for the clarification step; it is unknown what happens if a decision owner does not respond."
    },
    {
      "id": "G8",
      "description": "The criteria for identifying confidential content and the process for handling it before the email is sent are not defined."
    }
  ]
}
